// Turtle Sonar SDK: v1, at https://sonar.turtle.xyz/v1.
//
// One group per resource, as the spec tags them and the docs list them:
// `contacts.listContacts`, `engagements.moveEngagement`. Each group is a
// class of static methods generated by hey-api, so nothing needs to be
// instantiated. The client is pre-configured via runtime-config.ts (reads
// TURTLE_API_KEY and TURTLE_SONAR_BASE_URL from process.env), and is
// re-exported, with `createClient`, for the same overrides as Earn's.

export { createClient } from "./client/client";
export { client } from "./client/client.gen";
export * from "./client/sdk.gen";
export * as types from "./client/types.gen";
export * as schemas from "./client/zod.gen";
